    const grade = gradeOn(person, c.date);
    dues.get(c.date.slice(0, 7))!.push(claimDueNow(c, claims.data, rateFor(rates.data, grade, c.date), settings, today, grade));
  }
  return (
    <section data-testid="month-totals">
      <table>
        <thead>
          <tr>
            <th>Month</th>
            <th>Due total</th>
          </tr>
        </thead>
        <tbody>
