            <tr key={m}>
              <td>{m}</td>
              <td data-testid={`month-${m}-due-total`}>{sumDues(dues.get(m)!)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 42, Component: ({ sheetId }) => <MonthTotals sheetId={sheetId} /> });
